function createState(balance){return{money:balance.initialMoney,loanPayment:balance.loan.payment,loanPaymentsMade:0,loanPaymentsRequired:balance.loan.requiredPayments,heroLevel:balance.hero?.initialLevel||1,heroMaxHp:balance.hero?.initialMaxHp||30,heroAttack:balance.hero?.initialAttack||8,heroBattlesWon:0,bahamutValue:balance.bahamut.initialValue,bahamutCondition:balance.bahamut.initialCondition,bahamutTrust:balance.bahamut.initialTrust,bahamutBattleCount:0,chapter:1,route:"common",flags:{},endingId:null,finalAppraisal:null,defeatedBy:null}}
function change(state,type,key,value){if(type==="set")state[key]=value;else if(type==="add")state[key]=(Number(state[key])||0)+Number(value);else if(type==="subtract")state[key]=(Number(state[key])||0)-Number(value);if(key==="bahamutCondition")state[key]=Math.max(0,Math.min(100,state[key]));console.debug("Variable changed",key,state[key])}
function compare(a,op,b){return{"==":a==b,"!=":a!=b,">":a>b,">=":a>=b,"<":a<b,"<=":a<=b}[op]??false}
function appraisal(state,balance){const b=balance.bahamut,c=state.bahamutCondition,t=state.bahamutTrust,n=state.bahamutBattleCount;const condition=c>=90?b.conditionBonus["90"]:c>=70?b.conditionBonus["70"]:c>=50?b.conditionBonus["50"]:b.conditionBonus.below50;const trust=t>=20?b.trustBonus["20"]:t>=10?b.trustBonus["10"]:t<0?b.trustBonus.below0:b.trustBonus.default;const overuse=n>=6?b.overusePenalty["6"]:n>=4?b.overusePenalty["4"]:n>=3?b.overusePenalty["3"]:n>=2?b.overusePenalty["2"]:b.overusePenalty.default;return{value:state.bahamutValue+condition+trust+overuse,condition,trust,overuse}}

const KEY="zankure-bahamut-save-v1";const hasSave=()=>!!localStorage.getItem(KEY);function save(data){localStorage.setItem(KEY,JSON.stringify(data))}function load(){try{return JSON.parse(localStorage.getItem(KEY))}catch(e){console.warn("Save load failed",e);return null}}function clear(){localStorage.removeItem(KEY)}

function battleOptions(enemy,enemies){const data=enemies[enemy]||{name:enemy,battleType:"final",bahamutConditionCost:5,bahamutTrustOnHeroFight:2};if(data.battleType==="final")return[{text:`${data.name}に全力で挑む`,result:"win"},{text:"敗北ルートを確認する（BAD END C）",result:"lose"}];return[{text:"自分で戦う",result:"win",mode:"hero"},{text:"バハムートに任せる",result:"win",mode:"bahamut"},{text:"撤退に失敗する（BAD END C）",result:"lose"}]}
function applyBattleResult(state,enemy,enemies,option){const data=enemies[enemy]||{};if(option.result==="win"&&option.mode==="hero")state.bahamutTrust+=(data.bahamutTrustOnHeroFight||2);if(option.result==="win"&&option.mode==="bahamut"){state.bahamutCondition=Math.max(0,state.bahamutCondition-(data.bahamutConditionCost||5));state.bahamutBattleCount++}console.debug("Battle result",enemy,option)}
const isRpgBattle=enemy=>["goblin","orc","demon_soldier","wyvern","golem","demon_king","god"].includes(enemy);

const battleSpecs={
  goblin:{hp:26,damage:5,guard:2,breath:26},
  orc:{hp:40,damage:6,guard:2,breath:40},
  demon_soldier:{hp:48,damage:7,guard:3,breath:48,tactical:true,strongDamage:44,strongGuardDamage:4,normalName:"素早い斬撃",strongName:"渾身の溜め斬り"},
  wyvern:{hp:54,damage:8,guard:3,breath:54,tactical:true,strongDamage:18,strongGuardDamage:4,normalName:"爪撃",strongName:"灼熱ブレス"},
  golem:{hp:70,damage:7,guard:3,breath:70,tactical:true,strongDamage:22,strongGuardDamage:5,normalName:"岩石の拳",strongName:"大地を砕く重撃"},
  demon_king:{hp:98,damage:10,guard:4,breath:36,tactical:true,strongDamage:24,strongGuardDamage:6,normalName:"魔剣の一閃",strongName:"暗黒魔法"},
  god:{hp:200,damage:14,guard:5,breath:0,tactical:true,strongDamage:34,strongGuardDamage:7,normalName:"光の槍",strongName:"裁きの神罰",alliesAuto:true}
};

function createRpgBattle(enemy,enemies,state){
  const specs=battleSpecs[enemy]||{hp:30,damage:5,guard:2,breath:16};
  const finalBattle=["demon_king","god"].includes(enemy),heroLevel=finalBattle?Math.max(state.heroLevel||1,3):state.heroLevel||1,heroAttack=finalBattle?Math.max(state.heroAttack||8,12):state.heroAttack||8,heroMaxHp=finalBattle?Math.max(state.heroMaxHp||30,40):state.heroMaxHp||30;
  return{enemy,name:enemies[enemy]?.name||enemy,heroLevel,heroAttack,heroHp:heroMaxHp,heroMaxHp,heroMp:specs.tactical?6:0,heroMaxMp:specs.tactical?12:0,magicEnabled:!!specs.tactical,attackMagicCost:5,healMagicCost:6,enemyHp:specs.hp,enemyMaxHp:specs.hp,enemyDamage:specs.damage,guardDamage:specs.guard,bahamutDamage:specs.breath,strongDamage:specs.strongDamage||0,strongGuardDamage:specs.strongGuardDamage||0,normalAttackName:specs.normalName||"反撃",strongAttackName:specs.strongName||"強攻撃",enemyCharging:false,alliesAuto:!!specs.alliesAuto,bahamutAutoDamage:18,demonKingAutoDamage:14,turn:1,potionUsed:false,bahamutUsed:false,ended:false,growthApplied:false,log:specs.alliesAuto?`${enemies[enemy]?.name||enemy}が戦闘態勢に入った。\nバハムートと魔王が援護に入る！`:`${enemies[enemy]?.name||enemy}が戦闘態勢に入った。\n行動を選んでください。`}
}

const battleVariance=(turn,salt=0)=>(turn*2+salt)%5-2;
function performRpgAction(b,state,enemies,action){
  if(b.ended)return b;
  let damage=0,incoming=b.enemyDamage,message="",guarding=false;
  if(action==="attack"){
    damage=Math.max(1,b.heroAttack+(b.magicEnabled?battleVariance(b.turn):0));
    if(b.magicEnabled)b.heroMp=Math.min(b.heroMaxMp,b.heroMp+2);
    message=`主人公の斬撃！ ${b.name}に${damage}ダメージ。${b.magicEnabled?" MPが2回復した。":""}`;
  }else if(action==="guard"){
    guarding=true;incoming=b.guardDamage;
    if(b.magicEnabled)b.heroMp=Math.min(b.heroMaxMp,b.heroMp+4);
    message=`主人公は盾を構えた。受けるダメージを軽減！${b.magicEnabled?" MPが4回復した。":""}`;
  }else if(action==="attack_magic"&&b.magicEnabled&&b.heroMp>=b.attackMagicCost){
    b.heroMp-=b.attackMagicCost;damage=Math.max(1,b.heroAttack+10+battleVariance(b.turn,1));message=`主人公の雷撃魔法！ ${b.name}に${damage}ダメージ。`;
  }else if(action==="heal_magic"&&b.magicEnabled&&b.heroMp>=b.healMagicCost){
    b.heroMp-=b.healMagicCost;const healed=Math.min(24,b.heroMaxHp-b.heroHp);b.heroHp+=healed;message=`主人公は回復魔法を唱え、HPが${healed}回復した。`;
  }else if(action==="potion"&&!b.magicEnabled&&!b.potionUsed){
    const healed=Math.min(10,b.heroMaxHp-b.heroHp);b.heroHp+=healed;b.potionUsed=true;message=`ポーションを使い、HPが${healed}回復した。`;
  }else if(action==="bahamut"&&!b.bahamutUsed&&!b.alliesAuto){
    damage=b.bahamutDamage;b.bahamutUsed=true;state.bahamutCondition=Math.max(0,state.bahamutCondition-(enemies[b.enemy]?.bahamutConditionCost||5));state.bahamutBattleCount++;message=`バハムートの灼熱の息！ ${b.name}に${damage}ダメージ。`;
  }else return b;
  if(b.alliesAuto){damage+=b.bahamutAutoDamage+b.demonKingAutoDamage;message+=`\nバハムートの追撃！ ${b.bahamutAutoDamage}ダメージ。\n魔王の暗黒魔法！ ${b.demonKingAutoDamage}ダメージ。`}
  b.enemyHp=Math.max(0,b.enemyHp-damage);
  if(b.enemyHp<=0){b.ended=true;b.result="win";b.log=`${message}\n${b.name}を倒した！`;return b}
  if(b.magicEnabled){
    if(b.enemyCharging){incoming=guarding?b.strongGuardDamage:b.strongDamage;message+=`\n${b.name}の${b.strongAttackName}！ 主人公は${incoming}ダメージを受けた。`;b.enemyCharging=false}
    else{incoming=guarding?b.guardDamage:Math.max(1,b.enemyDamage+battleVariance(b.turn,2));message+=`\n${b.name}の${b.normalAttackName}！ 主人公は${incoming}ダメージを受けた。`;b.enemyCharging=true;message+=`\n${b.name}が力を溜めている。次は${b.strongAttackName}だ！`}
  }else message+=`\n${b.name}の反撃！ 主人公は${incoming}ダメージを受けた。`;
  b.heroHp=Math.max(0,b.heroHp-incoming);
  if(b.heroHp<=0){b.ended=true;b.result="lose";b.log=`${message}\n主人公は力尽きた……。`;return b}
  b.turn++;b.log=message;return b
}
function applyVictoryGrowth(state,balance,enemy){if(!["goblin","orc","demon_soldier","wyvern","golem"].includes(enemy))return null;state.heroBattlesWon=(state.heroBattlesWon||0)+1;state.heroLevel=(state.heroLevel||1)+1;state.heroMaxHp=(state.heroMaxHp||30)+(balance.hero?.hpGrowthPerWin||5);state.heroAttack=(state.heroAttack||8)+(balance.hero?.attackGrowthPerWin||2);return{level:state.heroLevel,maxHp:state.heroMaxHp,attack:state.heroAttack}}

const ui$=s=>document.querySelector(s);const els={title:ui$("#title-screen"),play:ui$("#play-screen"),ending:ui$("#ending-screen"),bg:ui$("#background"),text:ui$("#text"),speaker:ui$("#speaker"),next:ui$("#next-mark"),choices:ui$("#choices"),toast:ui$("#toast"),chapter:ui$("#chapter-card"),effect:ui$("#effect-layer"),status:ui$("#status"),debug:ui$("#debug-panel"),debugValues:ui$("#debug-values"),modal:ui$("#modal"),modalImage:ui$("#modal-image"),modalCaption:ui$("#modal-caption"),error:ui$("#error-box"),battle:ui$("#battle-panel")};
const preloadedImages=new Map(),resolvedAssetUrls=new Map();
const versioned=url=>`${url}?v=${window.CACHE_BUST}`,assetVariants=url=>url.toLowerCase().endsWith(".png")?[url.slice(0,-4)+".webp",url]:[url];
function loadPreferredAsset(url){if(preloadedImages.has(url))return preloadedImages.get(url);const promise=new Promise(resolve=>{const variants=assetVariants(url);let index=0;const tryNext=()=>{const candidate=variants[index++],img=new Image();img.onload=()=>{const found=versioned(candidate);resolvedAssetUrls.set(url,found);resolve(found)};img.onerror=()=>index<variants.length?tryNext():(console.warn("Asset preload failed:",url),resolve(versioned(url)));img.src=versioned(candidate)};tryNext()});preloadedImages.set(url,promise);return promise}
function setImageWithFallback(img,url,onMissing){const variants=assetVariants(url);let index=0;img.onerror=()=>{if(index<variants.length)img.src=versioned(variants[index++]);else{console.warn("Missing asset:",url);onMissing?.()}};img.src=versioned(variants[index++])}
function preloadVisualAssets(characters,enemies,scenarios){const urls=new Set();for(const scenario of Object.values(scenarios||{}))for(const scene of Object.values(scenario.scenes||{}))for(const step of scene.steps||[]){if(step.type==="background")urls.add(`../assets/backgrounds/${step.name}.png`);if(step.type==="showCharacter"){const expression=step.expression||characters[step.character]?.defaultExpression||"normal";urls.add(`../assets/characters/${step.character}/${step.character}_${expression}.png`)}if(step.type==="showEnemy"){const enemy=enemies[step.enemy]||{};urls.add(`../${enemy.asset||`assets/enemies/${step.enemy}.png`}`)}if(step.type==="document")urls.add(`../assets/documents/${step.name}.png`)}for(const url of urls)loadPreferredAsset(url);console.debug("Visual assets preloading",urls.size)}
function showScreen(name){[els.title,els.play,els.ending].forEach(x=>x.classList.remove("active"));({title:els.title,play:els.play,ending:els.ending}[name]).classList.add("active")}
function updateStatus(s,loc,debug,appraisalValue){els.status.classList.toggle("contract-locked",!s.flags?.signedContract);ui$("#money").textContent=loc(s.money);ui$("#payment").textContent=loc(s.loanPayment);ui$("#payments").textContent=`${s.loanPaymentsMade} / ${s.loanPaymentsRequired}`;const condition=s.bahamutCondition>=90?"良好":s.bahamutCondition>=60?"普通":"消耗";const trust=s.bahamutTrust>=15?"厚い":s.bahamutTrust>=5?"普通":"まだ薄い";const rank=appraisalValue>=90?"S":appraisalValue>=80?"A":appraisalValue>=70?"B":appraisalValue>=55?"C":"D";ui$("#bahamut-status").innerHTML=`状態：${condition}<br>信頼：${trust}<br>査定予想：${rank}`;if(debug)els.debugValues.textContent=JSON.stringify(s,null,2)}
function background(name){const url=`../assets/backgrounds/${name}.png`,path=resolvedAssetUrls.get(url)||versioned(url);els.bg.dataset.background=name;els.bg.style.backgroundImage=`url("${path}")`}
async function prepareBackground(name){if(!name)return;await loadPreferredAsset(`../assets/backgrounds/${name}.png`);background(name)}
async function sceneTransition(name){if(els.bg.dataset.background===name)return;await loadPreferredAsset(`../assets/backgrounds/${name}.png`);const oldBackground=getComputedStyle(els.bg).backgroundImage;els.play.classList.add("transitioning");els.effect.style.backgroundImage=oldBackground;els.effect.className="background-crossfade covered";void els.effect.offsetWidth;background(name);await new Promise(requestAnimationFrame);els.effect.classList.remove("covered");await new Promise(r=>setTimeout(r,570));els.effect.className="";els.effect.style.backgroundImage="";els.play.classList.remove("transitioning")}
function showCharacter(c,characters){document.querySelectorAll(`[data-character="${c.character}"]`).forEach(el=>el.remove());const slot=ui$( `.character-slot.${c.position||"center"}`);slot.innerHTML="";const img=new Image(),expression=c.expression||characters[c.character]?.defaultExpression||"normal",wanted=`../assets/characters/${c.character}/${c.character}_${expression}.png`,fallback=`../assets/characters/${c.character}/${c.character}_normal.png`;img.alt=characters[c.character]?.name||c.character;img.dataset.character=c.character;img.style.transform=`scale(${characters[c.character]?.scale||1})`;let usingFallback=false;const missing=()=>{if(!usingFallback&&wanted!==fallback){usingFallback=true;setImageWithFallback(img,fallback,missing)}else slot.innerHTML=`<div class="placeholder" data-character="${c.character}">${img.alt}</div>`};setImageWithFallback(img,wanted,missing);slot.append(img)}
function hideCharacter(id){document.querySelectorAll(`[data-character="${id}"]`).forEach(el=>el.remove())}function hideAll(){document.querySelectorAll(".character-slot").forEach(s=>s.innerHTML="")}
function showEnemy(id,enemies){const layer=ui$("#enemy-layer"),data=enemies[id]||{};els.play.classList.add("enemy-active");layer.innerHTML="";const img=new Image();img.alt=data.name||id;img.dataset.enemy=id;setImageWithFallback(img,`../${data.asset||`assets/enemies/${id}.png`}`,()=>layer.innerHTML=`<div class="placeholder" data-enemy="${id}">${img.alt}</div>`);layer.append(img)}function hideEnemy(){els.play.classList.remove("enemy-active");ui$("#enemy-layer").innerHTML=""}
function choices(options,handler){els.choices.innerHTML="";options.forEach((o,i)=>{const b=document.createElement("button");b.textContent=o.text;b.onclick=()=>{els.choices.innerHTML="";handler(o,i)};els.choices.append(b)})}
function renderRpgBattle(b,onAction){els.play.classList.add("battle-active");els.play.classList.toggle("god-battle",b.enemy==="god");els.play.classList.toggle("tactical-battle",b.magicEnabled);ui$("#battle-hero-hp").textContent=`HP ${b.heroHp} / ${b.heroMaxHp}`;ui$("#battle-hero-stats").textContent=`LV ${b.heroLevel}　攻撃力 ${b.heroAttack}`;ui$("#battle-hero-mp").textContent=`MP ${b.heroMp} / ${b.heroMaxMp}`;ui$("#battle-enemy-name").textContent=b.name;ui$("#battle-enemy-hp").textContent=`HP ${b.enemyHp} / ${b.enemyMaxHp}`;ui$("#battle-enemy-intent").textContent=b.enemyCharging?`次の行動：${b.strongAttackName}（防御推奨）`:`次の行動：${b.normalAttackName}`;ui$("#battle-hero-bar").style.width=`${b.heroHp/b.heroMaxHp*100}%`;ui$("#battle-hero-mp-bar").style.width=`${b.heroMaxMp?b.heroMp/b.heroMaxMp*100:0}%`;ui$("#battle-enemy-bar").style.width=`${b.enemyHp/b.enemyMaxHp*100}%`;ui$("#battle-turn").textContent=`TURN ${b.turn}`;ui$("#battle-log").textContent=b.log;document.querySelectorAll("[data-battle-action]").forEach(button=>{const action=button.dataset.battleAction,magicAction=["attack_magic","heal_magic"].includes(action);button.hidden=(action==="potion"&&b.magicEnabled)||(magicAction&&!b.magicEnabled);if(action==="attack_magic")button.textContent=`攻撃魔法 MP${b.attackMagicCost}`;if(action==="heal_magic")button.textContent=`回復魔法 MP${b.healMagicCost}`;if(action==="bahamut")button.textContent=b.alliesAuto?"仲間が自動攻撃":"バハムート";button.disabled=b.ended||(action==="potion"&&b.potionUsed)||(action==="attack_magic"&&b.heroMp<b.attackMagicCost)||(action==="heal_magic"&&(b.heroMp<b.healMagicCost||b.heroHp>=b.heroMaxHp))||(action==="bahamut"&&(b.bahamutUsed||b.alliesAuto));button.onclick=()=>onAction(action)})}function closeRpgBattle(){els.play.classList.remove("battle-active","god-battle","tactical-battle");document.querySelectorAll("[data-battle-action]").forEach(button=>{button.onclick=null;button.hidden=false;if(button.dataset.battleAction==="bahamut")button.textContent="バハムート"})}
function toast(text,ms=1150){return new Promise(r=>{els.toast.textContent=text;els.toast.classList.add("show");setTimeout(()=>{els.toast.classList.remove("show");r()},ms)})}
function chapter(title){els.play.classList.add("chapter-active");els.chapter.textContent=title;els.chapter.classList.add("show");return new Promise(resolve=>setTimeout(()=>{els.chapter.classList.remove("show");els.play.classList.remove("chapter-active");resolve()},1500))}
function effect(name){els.effect.className=name;setTimeout(()=>els.effect.className="",1000)}
function documentModal(name){return new Promise(resolve=>{setImageWithFallback(els.modalImage,`../assets/documents/${name}.png`);els.modalCaption.textContent=name==="bahamut_contract"?"バハムート残価クレジット契約書":"ローン請求書";els.modal.classList.add("open");const close=()=>{els.modal.classList.remove("open");els.modal.onclick=null;ui$("#modal-close").onclick=null;resolve()};els.modal.onclick=e=>{if(e.target===els.modal)close()};ui$("#modal-close").onclick=close})}
function ending(step){ui$("#ending-title").textContent=step.title;ui$("#ending-text").textContent=step.text;showScreen("ending")}
function error(message){els.error.textContent=message;els.error.style.display="block"}

const UI={els,preloadVisualAssets,showScreen,updateStatus,background,prepareBackground,sceneTransition,showCharacter,hideCharacter,hideAll,showEnemy,hideEnemy,choices,renderRpgBattle,closeRpgBattle,toast,chapter,effect,documentModal,ending,error};

const Save={hasSave,save,load,clear};

class ScenarioEngine{
 constructor({state,balance,characters,enemies,onState,onEnding,onAutosave}){Object.assign(this,{state,balance,characters,enemies,onState,onEnding,onAutosave});this.file="";this.data=null;this.scene="";this.index=0;this.locked=false;this.typing=false;this.fullText="";this.timer=null;this.visualState={background:null,characters:{},enemy:null}}
 async getJson(file,folder){try{const r=await fetch(`${folder}/${file}?v=${window.CACHE_BUST}`);if(!r.ok)throw Error(`${r.status}`);return await r.json()}catch(e){const key=file.replace(/\.json$/,'');const source=folder.includes("scenario")?window.SCENARIO_BUNDLE?.[key]:window.DATA_BUNDLE?.[key];if(source)return structuredClone(source);throw new Error(`${file} の読み込みに失敗しました: ${e.message}`)}}
 async load(file,scene=null,index=0){this.locked=true;this.file=file;this.data=await this.getJson(file,"../scenario");this.scene=scene||this.data.startScene;this.index=index;this.state.chapter=this.data.chapter;console.debug("Scenario loaded",file);console.debug("Scene changed",this.scene);const prefixVisual=this.deriveVisualState();if(!this.visualState?.background)this.visualState=prefixVisual;const openingBackground=this.visualState.background||this.data.scenes[this.scene]?.steps?.slice(this.index).find(step=>step.type==="background")?.name;this.onState();this.onAutosave();await UI.prepareBackground(openingBackground);if(!["route_normal.json","route_good.json"].includes(file))await UI.chapter(this.data.title);UI.hideAll();UI.hideEnemy();Object.values(this.visualState.characters||{}).forEach(c=>UI.showCharacter(c,this.characters));if(this.visualState.enemy)UI.showEnemy(this.visualState.enemy,this.enemies);this.locked=false;return this.run()}
 deriveVisualState(){const visual={background:null,characters:{},enemy:null};for(const step of this.data.scenes[this.scene]?.steps?.slice(0,this.index)||[]){if(step.type==="background")visual.background=step.name;if(step.type==="showCharacter"){for(const[pos,c]of Object.entries(visual.characters))if(c.character===step.character)delete visual.characters[pos];visual.characters[step.position||"center"]={...step}}if(step.type==="hideCharacter")for(const[pos,c]of Object.entries(visual.characters))if(c.character===step.character)delete visual.characters[pos];if(step.type==="hideAllCharacters")visual.characters={};if(step.type==="showEnemy")visual.enemy=step.enemy;if(step.type==="hideEnemy")visual.enemy=null}return visual}
 current(){return this.data?.scenes?.[this.scene]?.steps?.[this.index]}
 goto(scene){if(!this.data.scenes[scene])throw Error(`存在しないscene: ${this.file} / ${scene}`);this.scene=scene;this.index=0;console.debug("Scene changed",scene);this.run()}
 advance(){if(this.locked)return;if(this.typing){this.finishTyping();return}this.index++;this.run()}
 async run(){try{let guard=0;while(!this.locked){if(++guard>100)throw Error("自動実行stepが100件を超えました");const step=this.current();if(!step)throw Error(`stepがありません: ${this.file}/${this.scene}/${this.index}`);console.debug("Step executed",step.type,this.file,this.scene,this.index);const pause=await this.execute(step);this.onState();if(pause)return;this.index++}}catch(e){console.error(e);UI.error(`進行エラー: ${e.message}`)}}
 async execute(s){switch(s.type){
 case"dialogue":case"narration":this.say(s);return true;
 case"background":this.locked=true;this.finishTyping();await UI.sceneTransition(s.name);this.visualState.background=s.name;this.locked=false;break;
 case"showCharacter":for(const[pos,c]of Object.entries(this.visualState.characters))if(c.character===s.character)delete this.visualState.characters[pos];this.visualState.characters[s.position||"center"]={...s};UI.showCharacter(s,this.characters);break;
 case"hideCharacter":for(const[pos,c]of Object.entries(this.visualState.characters))if(c.character===s.character)delete this.visualState.characters[pos];UI.hideCharacter(s.character);break;
 case"hideAllCharacters":this.visualState.characters={};UI.hideAll();break;
 case"showEnemy":this.visualState.enemy=s.enemy;UI.showEnemy(s.enemy,this.enemies);break;
 case"hideEnemy":this.visualState.enemy=null;UI.hideEnemy();break;
 case"choice":this.locked=true;UI.choices(s.options,async o=>{for(const a of o.actions||[])await this.action(a);this.locked=false;this.goto(o.next||o.scene)});return true;
 case"set":case"add":case"subtract":change(this.state,s.type,s.variable,s.value);if(s.variable==="route")console.debug("Route changed",s.value);break;
 case"setFlag":this.state.flags[s.flag]=s.value;console.debug("Flag changed",s.flag,s.value);break;
 case"condition":this.goto(compare(this.state[s.variable],s.operator,s.value)?s.trueNext:s.falseNext);return true;
 case"conditionFlag":this.goto(this.state.flags[s.flag]===s.value?s.trueNext:s.falseNext);return true;
 case"jump":this.goto(s.scene);return true;
 case"loadScenario":UI.hideAll();UI.hideEnemy();this.visualState={background:null,characters:{},enemy:null};await this.load(s.file);return true;
 case"battle":this.doBattle(s);return true;
 case"reward":await this.reward(s);break;
 case"loanPayment":await this.loan(s);return true;
 case"appraisal":await this.appraise(s);return true;
 case"ending":console.debug("Ending reached",s.id);this.locked=true;UI.ending(s);this.onEnding(s);return true;
 case"statusMessage":this.locked=true;await UI.toast(`${s.text}\n${Number(this.state[s.variable]).toLocaleString("ja-JP")}${s.suffix||""}`);this.locked=false;break;
 case"effect":UI.effect(s.name);break;
 case"wait":this.locked=true;await new Promise(r=>setTimeout(r,Math.min(s.duration||0,2500)));this.locked=false;break;
 case"eventCG":await UI.documentModal(`../events/${s.name}`);break;
 case"document":this.locked=true;await UI.documentModal(s.name);this.locked=false;break;
 default:console.warn("Unknown scenario step type:",s.type);break}return false}
 async action(a){if(["set","add","subtract"].includes(a.type))change(this.state,a.type,a.variable,a.value);else if(a.type==="setFlag")this.state.flags[a.flag]=a.value;else console.warn("Unknown choice action:",a.type)}
 say(s){this.fullText=s.text||"";UI.els.speaker.textContent=s.type==="dialogue"?(this.characters[s.speaker]?.name||this.enemies[s.speaker]?.name||s.speaker):"";UI.els.text.textContent="";UI.els.next.style.display="none";this.typing=true;let i=0;clearInterval(this.timer);this.timer=setInterval(()=>{UI.els.text.textContent=this.fullText.slice(0,++i);if(i>=this.fullText.length)this.finishTyping()},this.balance.ui.typewriterMsPerCharacter||25)}
 finishTyping(){clearInterval(this.timer);UI.els.text.textContent=this.fullText;UI.els.next.style.display="block";this.typing=false}
 doBattle(s){if(isRpgBattle(s.enemy)){this.doRpgBattle(s);return}this.locked=true;UI.els.speaker.textContent="BATTLE";UI.els.text.textContent=`${this.enemies[s.enemy]?.name||s.enemy}が現れた！`;UI.choices(battleOptions(s.enemy,this.enemies),o=>{applyBattleResult(this.state,s.enemy,this.enemies,o);this.locked=false;this.goto(o.result==="win"?s.winNext:s.loseNext)})}
 doRpgBattle(s){this.locked=true;this.finishTyping();const battle=createRpgBattle(s.enemy,this.enemies,this.state);const render=()=>UI.renderRpgBattle(battle,action=>{performRpgAction(battle,this.state,this.enemies,action);this.onState();render();if(battle.ended)setTimeout(async()=>{await UI.toast(battle.result==="win"?"BATTLE WIN":"BATTLE LOST",850);if(battle.result==="win"&&!battle.growthApplied){battle.growthApplied=true;if(!battle.bahamutUsed)this.state.bahamutTrust+=this.enemies[s.enemy]?.bahamutTrustOnHeroFight||2;const growth=applyVictoryGrowth(this.state,this.balance,s.enemy);if(growth)await UI.toast(`LEVEL UP\nLV ${growth.level}\n最大HP ${growth.maxHp} / 攻撃力 ${growth.attack}`,1400)}if(battle.result==="lose")this.state.defeatedBy=s.enemy;UI.closeRpgBattle();this.locked=false;this.goto(battle.result==="win"?s.winNext:s.loseNext)},650)});render()}
 async reward(s){this.locked=true;const amount=s.amount??this.balance.rewards[s.enemy]??0;this.state.money+=amount;console.debug("Reward received",amount);this.onState();await UI.toast(`QUEST CLEAR\n${s.label||"討伐報酬"}\n+${amount.toLocaleString("ja-JP")} G`);this.locked=false}
 async loan(s){this.locked=true;const amount=s.amount??this.state.loanPayment;await UI.toast(`BAHAMUT LOAN\n今月のお支払い\n-${amount.toLocaleString("ja-JP")} G`);if(this.state.money>=amount){this.state.money-=amount;this.state.loanPaymentsMade++;console.debug("Loan payment",amount);this.onState();await UI.toast(`支払い完了\n現在の所持金\n${this.state.money.toLocaleString("ja-JP")} G`);this.locked=false;this.goto(s.successNext)}else{console.debug("Loan payment failed",this.state.money);this.locked=false;this.goto(s.failureNext)} }
 async appraise(s){this.locked=true;const result=appraisal(this.state,this.balance);this.state.finalAppraisal=result.value;const rank=result.value>=90?"S":result.value>=80?"A":result.value>=70?"B":result.value>=55?"C":"D";await UI.toast(`FINAL APPRAISAL\n査定ランク ${rank}\n評価値 ${result.value}\n基礎 ${this.state.bahamutValue} / 状態 ${result.condition>=0?"+":""}${result.condition} / 信頼 ${result.trust>=0?"+":""}${result.trust} / 酷使 ${result.overuse}` ,1800);this.locked=false;this.goto(result.value>=(s.requiredValue??this.balance.bahamut.normalEndingRequiredValue)?s.successNext:s.failureNext)}
 snapshot(){return{gameState:this.state,scenarioFile:this.file,sceneId:this.scene,stepIndex:this.index,visualState:this.visualState}}
}

let balance,characters,enemies,state,engine,DEBUG_MODE=false;const $=s=>document.querySelector(s),currency=n=>`${Number(n).toLocaleString("ja-JP")} G`;
async function data(name){try{const r=await fetch(`data/${name}.json?v=${window.CACHE_BUST}`);if(!r.ok)throw Error(r.status);return await r.json()}catch(e){const d=window.DATA_BUNDLE?.[name];if(d)return structuredClone(d);throw Error(`${name}.json を読み込めません: ${e.message}`)}}
async function boot(){try{[balance,characters,enemies]=await Promise.all([data("game_balance"),data("characters"),data("enemies")]);DEBUG_MODE=false;UI.preloadVisualAssets(characters,enemies,window.SCENARIO_BUNDLE);$("#continue-btn").disabled=!Save.hasSave();wire()}catch(e){UI.error(`起動エラー: ${e.message}`)}}
function wire(){$("#start-btn").onclick=()=>start(false);$("#debug-start-btn").onclick=()=>start(true);$("#continue-btn").onclick=continueGame;$("#title-btn").onclick=()=>{UI.showScreen("title");$("#continue-btn").disabled=!Save.hasSave()};$("#save-btn").onclick=()=>{Save.save(engine.snapshot());UI.toast("SAVE COMPLETE")};UI.els.play.addEventListener("click",e=>{if(e.target.closest("button")||UI.els.modal.classList.contains("open"))return;engine?.advance()});addEventListener("keydown",e=>{if((e.key==="Enter"||e.code==="Space")&&!UI.els.modal.classList.contains("open")){e.preventDefault();engine?.advance()}});document.querySelectorAll("[data-debug]").forEach(b=>b.onclick=()=>{const k=b.dataset.debug,{moneyIncrement,bahamutValueIncrement,bahamutConditionIncrement,bahamutTrustIncrement}=balance.debug;if(k==="money")state.money+=moneyIncrement;if(k==="value")state.bahamutValue+=bahamutValueIncrement;if(k==="condition")state.bahamutCondition=Math.min(100,state.bahamutCondition+bahamutConditionIncrement);if(k==="trust")state.bahamutTrust+=bahamutTrustIncrement;render()})}
function makeEngine(){engine=new ScenarioEngine({state,balance,characters,enemies,onState:render,onEnding:()=>Save.clear(),onAutosave:()=>Save.save(engine.snapshot())})}
async function start(debug){state=createState(balance);DEBUG_MODE=debug;makeEngine();UI.els.play.classList.add("chapter-active");UI.showScreen("play");UI.els.debug.classList.toggle("active",DEBUG_MODE);await engine.load("chapter01_intro.json")}
async function continueGame(){const s=Save.load();if(!s)return;DEBUG_MODE=false;state={...createState(balance),...s.gameState,flags:{...(s.gameState.flags||{})}};makeEngine();if(s.visualState)engine.visualState=s.visualState;UI.els.play.classList.add("chapter-active");UI.showScreen("play");UI.els.debug.classList.remove("active");await engine.load(s.scenarioFile,s.sceneId,s.stepIndex)}
function render(){UI.updateStatus(state,currency,DEBUG_MODE,appraisal(state,balance).value);if(DEBUG_MODE&&engine)UI.els.debugValues.textContent+=`\ncurrent: ${engine.file} / ${engine.scene} / ${engine.index}`}
boot();

